def segs(inp):
    # find separator columns (all same color, appearing as vertical lines)
    h,w=len(inp),len(inp[0])
    # separator color 3: columns fully 3? not necessarily full; find columns whose values are a single nonzero color not part of segments
    cols=[]
    for j in range(w):
        col={inp[i][j] for i in range(h)}
        if len(col)==1 and 3 in col: cols.append(j)
    # group into segments
    bounds=[]; start=0
    for j in cols+[w]:
        bounds.append((start,j)); start=j+1
    return cols,bounds

