def extract(inp):
    h,w=len(inp),len(inp[0])
    cols=[j for j in range(w) if {inp[i][j] for i in range(h)}=={3}]
    bounds=[];start=0
    for j in cols+[w]: bounds.append((start,j)); start=j+1
    bounds=[b for b in bounds if b[1]>b[0]]
    return bounds

