def feat(seg,c,i,j):
    blk=seg[c]; h=4; w=len(blk[0])
    nb4=sum(1 for di,dj in [(1,0),(-1,0),(0,1),(0,-1)] if 0<=i+di<h and 0<=j+dj<w and blk[i+di][j+dj])
    nb8=sum(1 for di in (-1,0,1) for dj in (-1,0,1) if (di or dj) and 0<=i+di<h and 0<=j+dj<w and blk[i+di][j+dj])
    # horizontal run length at (i,j)
    a=j
    while a>0 and blk[i][a-1]: a-=1
    b=j
    while b<w-1 and blk[i][b+1]: b+=1
    hrun=b-a+1
    a=i
    while a>0 and blk[a-1][j]: a-=1
    b=i
    while b<h-1 and blk[b+1][j]: b+=1
    vrun=b-a+1
    # component size via BFS
    seen={(i,j)}; st=[(i,j)]
    while st:
        x,y=st.pop()
        for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx,ny=x+dx,y+dy
            if 0<=nx<h and 0<=ny<w and blk[nx][ny] and (nx,ny) not in seen:
                seen.add((nx,ny)); st.append((nx,ny))
    d=counts(seg,c,i,j)
    return dict(nb4=nb4,nb8=nb8,hrun=hrun,vrun=vrun,comp=len(seen),**d)

