def block_colors(block):
    """The set of nonzero colors in a block."""
    return {v for row in block for v in row if v}

def overlay(blocks, priority):
    """Cellwise overlay of same-shape blocks; each cell gets the block color highest in priority."""
    h, w = len(blocks[0]), len(blocks[0][0])
    rank = {c: len(priority) - 1 - i for i, c in enumerate(priority)}
    out = [[0] * w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            cands = [blk[i][j] for blk in blocks if blk[i][j]]
            out[i][j] = max(cands, key=lambda c: rank[c])
    return out
